user_id = #{userId}, plot_id = #{plotId}, batch_id = #{batchId}, task_title = #{taskTitle}, task_type = #{taskType}, task_content = #{taskContent}, priority = #{priority}, deadline_time = #{deadlineTime}, actual_start_time = #{actualStartTime}, actual_end_time = #{actualEndTime}, status = #{status}, executor_id = #{executorId}, complete_remark = #{completeRemark}, remark = #{remark}, source_type = #{sourceType}, source_id = #{sourceId}, ai_solution_id = #{aiSolutionId},
